def words_to_numbers(words):
    # We use dictionary comprehension to define the mapping
    mapping = {chr(i): i-96 for i in range(97,123)}

    # We split each word into a list of letters, apply the mapping and join them together
    return '-'.join(str(mapping[letter]) for letter in words.lower())

# Let's test the function
print(words_to_numbers("BARK"))  # Output: '2-2-0-3-2'
print(words_to_numbers("NO"))  # Output: '6-0'

